from json import dumps
R,C=22,26
g=[[0]*C for _ in range(R)]
# Frame rectangles retain their borders; scattered digits indicate the fill color, scattered 5s are noise.
frames=[(1,6,3,11,1,4),(10,13,2,5,2,8),(9,16,11,21,3,5)]
for r0,r1,c0,c1,border,fill in frames:
 for r in range(r0,r1+1):
  for c in range(c0,c1+1):
   if r in (r0,r1) or c in (c0,c1): g[r][c]=border
 # Pattern determined by aspect ratio: wide interiors alternate on every cell; tall interiors checkerboard.
 for r in range(r0+1,r1):
  for c in range(c0+1,c1):
   if (r1-r0==2) or ((r-r0-1+c-c0-1)%2==0): g[r][c]=fill
print(dumps(g,separators=(',',':')))
